/* 控制点也要落在「圆外一点」的合理位置（kappa ≈ 0.5523 的经典近似值）*/
const k = Math.abs(c1.segs[0][0][0] - 40);
assert.ok(k > 0.5 && k < 0.6, "第一段控制点偏移 ≈ 0.5523·r（贝塞尔近似系数）：" + k.toFixed(4));

