/* 控制点要落在「贝塞尔近似」该在的位置：第一段从 θ=0 出发、沿 +y 切出，
   所以 kappa 体现在**纵坐标**偏移上（c1 = (x+rx, y + k·ry)，k ≈ 0.5523）*/
const kappa = Math.abs(c1.segs[0][0][1] - 20) / 30;
assert.ok(kappa > 0.5 && kappa < 0.6,
  "第一段控制点纵偏移 / r ≈ 0.5523（贝塞尔近似系数）：" + kappa.toFixed(4));
